/** test numbers_start_at_one (todo/tests/scenarios.slg:8) */
export function numbersStartAtOne(w: World): null {
  check.expect(
    () => board.add(w, "milk"),
    () => 1n,
  );
  check.expect(
    () => board.add(w, "bread", undefined, rt.OrdSet.of(rt.text, ["shop", "home"])),
    () => 2n,
  );
  check.assert(w.fx.out.text() === "added 1\nadded 2\n");
  return null;
}

/** test numbers_are_never_reused (todo/tests/scenarios.slg:14) */
export function numbersAreNeverReused(w: World): null {
  check.expect(
    () => board.add(w, "a"),
    () => 1n,
  );
  check.expect(
    () => board.add(w, "b"),
    () => 2n,
  );
  board.remove(w, 2n);
  check.expect(
    () => board.add(w, "c"),
    () => 3n,
  );
  return null;
}

/** test empty_board_says_so (todo/tests/scenarios.slg:21) */
export function emptyBoardSaysSo(w: World): null {
  board.list(w);
  board.stats(w);
  check.assert(w.fx.out.text() === "nothing to do\n0 open, 0 done\n");
  return null;
}

/** test list_ranks_urgent_first (todo/tests/scenarios.slg:27) */
export function listRanksUrgentFirst(w: World): null {
  board.list(w);
  check.assert(w.fx.out.text() === "3 [ ] urgent !high #work\n2 [ ] plain\n1 [ ] low one !low\n");
  return null;
}

/** test list_all_and_by_tag (todo/tests/scenarios.slg:33) */
export function listAllAndByTag(w: World): null {
  board.list(w, true, rt.some("work"));
  check.assert(w.fx.out.text() === "3 [ ] urgent !high #work\n4 [x] finished #home #work\n");
  return null;
}

/** test done_and_reopen_move_once (todo/tests/scenarios.slg:39) */
export function doneAndReopenMoveOnce(w: World): null {
  board.done(w, 2n);
  check.expectFail(() => board.done(w, 2n), "AlreadyDone");
  board.reopen(w, 2n);
  check.expectFail(() => board.reopen(w, 2n), "NotDone");
  check.assert(w.fx.out.text() === "2 [x] plain\n2 [ ] plain\n");
  return null;
}

/** test rename_keeps_the_rest (todo/tests/scenarios.slg:48) */
export function renameKeepsTheRest(w: World): null {
  board.rename(w, 3n, "urgent, really");
  check.assert(
    rt.equal(
      w.tasks.at(3n),
      model.Task.make([3n, "urgent, really", undefined, model.Priority.make("High"), rt.OrdSet.of(rt.text, ["work"])]),
    ),
  );
  return null;
}

/** test clear_removes_only_done (todo/tests/scenarios.slg:54) */
export function clearRemovesOnlyDone(w: World): null {
  check.expect(
    () => board.clear(w),
    () => 1n,
  );
  board.stats(w);
  check.assert(w.fx.out.text() === "cleared 1\n3 open, 0 done\n");
  check.assert(!w.tasks.has(4n));
  return null;
}

/** test unknown_numbers_are_refused (todo/tests/scenarios.slg:62) */
export function unknownNumbersAreRefused(w: World, no: bigint): null {
  if (no <= 4n) {
    return null;
  }
  check.expectFail(() => board.done(w, no), "NoTask");
  check.expectFail(() => board.reopen(w, no), "NoTask");
  check.expectFail(() => board.rename(w, no, "x"), "NoTask");
  check.expectFail(() => board.remove(w, no), "NoTask");
  check.assert(w.fx.out.text() === "");
  return null;
}
